    static readonly Dictionary<int, UplinkElementDefinition> ById = All.ToDictionary(e => e.Id);

    public static UplinkElementDefinition? Find(int id)
    {
        return ById.TryGetValue(id, out var definition) ? definition : null;
    }

    public static UplinkElementDefinition Get(int id)
    {
        if (!ById.TryGetValue(id, out var definition))
        {
            throw new KeyNotFoundException($"UM{id} is not a FANS 1/A uplink message element.");
        }

        return definition;
    }
